package com.mantou.salesdialer.contacts;
import java.util.*;
import static com.mantou.salesdialer.contacts.PhoneIntakeModel.*;
public final class LocalDraftBatchCheck {
 static int checks;static final String SLOT="a".repeat(32);static LocalDraftBinding.Snapshot c(int id,long rev,Qualification q,boolean refused){return LocalDraftBinding.snapshot(DataClass.FORMAT_FIXTURE,SLOT,"LOCAL-TARGET-"+String.format("%032x",id),rev,q,refused,"GENERATED_BATCH_CHECK");}
 static void ok(boolean b,String message){checks++;if(!b)throw new AssertionError(message);}static void bad(Runnable r,String message){try{r.run();throw new AssertionError(message);}catch(IllegalArgumentException|IllegalStateException expected){checks++;}}
 public static void main(String[] args){
 var a=c(1,1,Qualification.CONFIRMED,false);var b=c(2,1,Qualification.UNKNOWN,false);var cc=c(3,1,Qualification.WITHDRAWN,false);var d=c(4,2,Qualification.CONFIRMED,true);var e=c(5,1,Qualification.CONFIRMED,false);var f=c(6,2,Qualification.CONFIRMED,false);var old=LocalDraftBinding.create(c(6,1,Qualification.CONFIRMED,false));var current=LocalDraftBinding.create(e);
 var input=new ArrayList<>(List.of(a,b,cc,d,e,f));var p=LocalDraftBatch.prepare(DataClass.FORMAT_FIXTURE,SLOT,input,List.of(current,old));
 ok(p.rows.size()==6,"complete preview");ok(p.count(LocalDraftBatch.Status.CREATE)==1,"one new eligible draft");ok(p.count(LocalDraftBatch.Status.NOT_QUALIFIED)==2,"unknown and withdrawn skipped");ok(p.count(LocalDraftBatch.Status.REFUSED)==1,"refusal dominates");ok(p.count(LocalDraftBatch.Status.EXISTING_CURRENT)==1,"current preserved");ok(p.count(LocalDraftBatch.Status.EXISTING_STALE)==1,"no implicit refresh");
 Collections.reverse(input);ok(p.sameSnapshot(LocalDraftBatch.prepare(DataClass.FORMAT_FIXTURE,SLOT,input,List.of(old,current))),"order independent snapshot");input.clear();ok(p.rows.size()==6,"immutable preview input snapshot");try{p.rows.clear();throw new AssertionError("mutable preview");}catch(UnsupportedOperationException expected){checks++;}
 var changed=List.of(c(1,2,Qualification.WITHDRAWN,false),b,cc,d,e,f);ok(!p.sameSnapshot(LocalDraftBatch.prepare(DataClass.FORMAT_FIXTURE,SLOT,changed,List.of(current,old))),"withdrawal invalidates confirmation");ok(!p.sameSnapshot(LocalDraftBatch.prepare(DataClass.FORMAT_FIXTURE,SLOT,List.of(a,b,cc,d,e,f),List.of(current))),"draft changes invalidate confirmation");ok(!p.sameSnapshot(null),"missing confirmation rejected");
 bad(()->LocalDraftBatch.prepare(DataClass.FORMAT_FIXTURE,SLOT,List.of(a,a),List.of()),"duplicate target");bad(()->LocalDraftBatch.prepare(DataClass.LOCAL_PHONE_INTAKE,SLOT,List.of(a),List.of()),"cross data class");bad(()->LocalDraftBatch.prepare(DataClass.FORMAT_FIXTURE,"b".repeat(32),List.of(a),List.of()),"cross slot");bad(()->LocalDraftBatch.prepare(DataClass.FORMAT_FIXTURE,SLOT,List.of(a),List.of(current)),"orphan draft");bad(()->LocalDraftBatch.prepare(DataClass.FORMAT_FIXTURE,SLOT,List.of(e),List.of(current,current)),"duplicate draft");bad(()->LocalDraftBatch.prepare(DataClass.FORMAT_FIXTURE,SLOT,null,List.of()),"null rows");bad(()->LocalDraftBatch.prepare(null,SLOT,List.of(),List.of()),"empty invalid scope");
 ok(LocalDraftBatch.prepare(DataClass.FORMAT_FIXTURE,SLOT,List.of(),List.of()).rows.isEmpty(),"empty preview");var many=new ArrayList<LocalDraftBinding.Snapshot>();for(int i=1;i<=201;i++)many.add(c(i,1,Qualification.CONFIRMED,false));var large=LocalDraftBatch.prepare(DataClass.FORMAT_FIXTURE,SLOT,many,List.of());ok(large.count(LocalDraftBatch.Status.CREATE)==201,"200 is not a lifetime or daily hard limit");System.out.println("LocalDraftBatchCheck passed "+checks+" assertions");
 }
}
